// Generator of the extended puzzles. Because the skeleton is fixed, a puzzle is generated by dealing traits to edges
// rather than by search, in constant time and with no verification step:
//   1. every internal edge receives at least one trait, so the leaf data determine the tree up to its symmetries;
//   2. in every cherry one of the two pendant edges receives a trait, so no two creatures are identical;
//   3. for every trait the side of the split that "has" it is chosen at random;
//   4. the creature at each end is the set of traits whose "has" side contains that end.
// For a level that should contain no perfect phylogeny, one more trait is added whose carrier set crosses an
// internal edge; together with that edge's trait it exhibits all four configurations, so no placement can succeed.

import { FEAT_IDS, keyOf, mulberry32, shuffleWith as shufR } from "../creatures.js";
import { SK } from "./skeletons.js";
import { findViolation } from "./rules.js";

export function genPuzzle(stage, seed) {
  const skelName = Array.isArray(stage.skel) ? stage.skel[Math.floor(mulberry32(seed)() * stage.skel.length)] : stage.skel;
  const sk = SK[skelName];
  for (let att = 0; att < 200; att++) {
    const R = mulberry32(seed + att * 7919);
    const pool = shufR(FEAT_IDS, R); let k = 0; const onEdge = {}; const load = {};
    const put = (i) => { onEdge[pool[k++]] = i; load[i] = (load[i] || 0) + 1; };
    sk.internal.forEach(put); // every internal edge carries a trait, so the data determine the tree
    for (let j = 0; j < (stage.extra || 0); j++) { const c = sk.internal.filter((i) => load[i] < 2); if (!c.length) break; put(c[Math.floor(R() * c.length)]); }
    const pend = sk.cherries.map((pair) => pair[Math.floor(R() * 2)]); // the two ends of a cherry must differ
    const rest = shufR(sk.leafIds.filter((l) => !pend.includes(l)), R);
    while (pend.length < (stage.pend || 0) && rest.length) pend.push(rest.pop());
    pend.forEach((l) => put(sk.edgeOfLeaf[l]));
    const names = Object.keys(onEdge); let feats = null;
    for (let o = 0; o < 80; o++) {
      const f = {}; sk.leafIds.forEach((l) => { f[l] = []; });
      names.forEach((t) => { const i = onEdge[t]; const pA = sk.internal.includes(i) ? 0.5 : sk.leafA[i].length === 1 ? 0.7 : 0.3; (R() < pA ? sk.leafA[i] : sk.leafB[i]).forEach((l) => f[l].push(t)); });
      feats = f; const sizes = sk.leafIds.map((l) => f[l].length);
      if (Math.min(...sizes) >= 1 && Math.max(...sizes) <= 5) break;
    }
    const wantConflict = stage.conflict === "yes" || (stage.conflict === "maybe" && R() < 0.5);
    if (wantConflict) {
      // one more trait whose pattern crosses an internal edge: with that edge's trait it shows all four configurations
      const cands = sk.internal.filter((i) => sk.leafA[i].length >= 2 && sk.leafB[i].length >= 2);
      const i = cands[Math.floor(R() * cands.length)];
      const part = (arr) => shufR(arr, R).slice(0, 1 + Math.floor(R() * (arr.length - 1)));
      const z = pool[k++]; [...part(sk.leafA[i]), ...part(sk.leafB[i])].forEach((l) => feats[l].push(z)); onEdge[z] = -1;
    }
    const keys = sk.leafIds.map((l) => keyOf(feats[l])); if (new Set(keys).size !== keys.length) continue;
    const traits = shufR(Object.keys(onEdge), R);
    const letters = {}; traits.forEach((t) => { const b = "ACGT"[Math.floor(R() * 4)]; let a = b; while (a === b) a = "ACGT"[Math.floor(R() * 4)]; letters[t] = [b, a]; });
    const tiles = shufR(sk.leafIds.map((l) => ({ id: "t" + l, feats: feats[l] })), R);
    const violation = findViolation(tiles, traits);
    if (!!violation !== wantConflict) continue;
    return { sk, skelName, traits, letters, tiles, conflict: wantConflict, violation };
  }
  return null;
}

