export const freeStage = (seed) => { const R = mulberry32(seed); const skel = ["s5", "s6c", "s6s"][Math.floor(R() * 3)]; const choose = skel !== "s5" && R() < 0.5; return { skel: choose ? ["s6c", "s6s"] : skel, chooseSkel: choose, pend: 3 + Math.floor(R() * 3), extra: R() < 0.4 ? 1 : 0, edgeTask: R() < 0.5, conflict: "maybe", view: R() < 0.4 ? "dna" : "morph", free: true, title: "חידה חופשית", note: choose ? "גם צורת העץ לא ידועה. בחרו, שבצו, ואם אין עץ, הוכיחו." : "אולי יש עץ מתאים ואולי לא. אם יש, בנו אותו. אם אין, הוכיחו." }; };
